/* Embeds the SD signature as a data URI so PDF/PNG exports also work when index.html
   is opened straight from disk (file://), where browsers block exporting canvases that
   contain local image files. */
(() => {
  const SIG = 'data:image/png;base64,';
  document.querySelectorAll('img[src$="sd-signature.png"]').forEach((img) => { img.src = SIG; });
})();

